function aiOverview(r){const ai=r.aiOverview;if(!ai||!Array.isArray(ai.paragraphs)||!ai.paragraphs.length)return '';return `<section class="ai-overview" aria-label="AI overview"><h3>AI-generated overview</h3><p class="overview-source">Gemini · ${escape(new Date(ai.generatedAt).toLocaleDateString())} · Based on author-provided information</p>${ai.paragraphs.slice(0,2).map(p=>`<p>${escape(p.text)}</p>`).join('')}<details><summary>Sources for this summary</summary>${ai.paragraphs.flatMap(p=>p.evidenceQuotes||[]).slice(0,6).map(q=>`<blockquote>${escape(q)}</blockquote>`).join('')}${ai.sourceUrl?`<a class="overview-link" href="${escape(protectedLink(safeUrl(ai.sourceUrl)))}" target="_blank" rel="noopener">Read the original source ↗</a>`:''}</details></section>`}
function projectOverview(r){const overview=r.overview;if(overview?.kind!=='readme')return '';const paragraphs=Array.isArray(overview.paragraphs)?overview.paragraphs.filter(p=>typeof p==='string'&&p.trim()&&p.trim().toLowerCase()!==String(r.description||'').trim().toLowerCase()&&p!==r.projectInsights?.whatItDoes?.text).slice(0,3):[];const features=Array.isArray(overview.features)?overview.features.filter(p=>typeof p==='string'&&p.trim()).slice(0,5):[];if(!paragraphs.length&&!features.length)return '';const source=safeUrl(overview.sourceUrl);return `<section class="project-overview" aria-label="Project overview"><h3>About this project</h3><p class="overview-source">From the project’s README · Author-written excerpt</p>${paragraphs.map(p=>`<p>${escape(p)}</p>`).join('')}${features.length?`<h4>Features from the README</h4><ul>${features.map(f=>`<li>${escape(f)}</li>`).join('')}</ul>`:''}${source?`<a class="overview-link" href="${escape(protectedLink(source))}" target="_blank" rel="noopener">Read the full README ↗</a>`:''}</section>`}
